import React, { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { FileText, Download, Loader, Check } from 'lucide-react'
import { extractDetectionMetrics, extractTrust, extractSecurityCounters, extractVerification } from '../lib/metrics'

const DATA_SOURCE_NOTE =
  'All quantitative results in this report are generated by the QShield Twin simulation ' +
  'using synthetic ground-truth labels. They characterise the simulator, not real-world ' +
  'field performance, and must not be cited as validated security guarantees.'

interface ReportSection {
  title: string
  content: string
  status: 'pending' | 'generating' | 'complete'
}

export default function ResearchReportGenerator() {
  const [reportSections, setReportSections] = useState<ReportSection[]>([
    { title: 'Title Page', content: '', status: 'pending' },
    { title: 'Abstract', content: '', status: 'pending' },
    { title: 'Introduction', content: '', status: 'pending' },
    { title: 'Methodology', content: '', status: 'pending' },
    { title: 'Results', content: '', status: 'pending' },
    { title: 'Analysis', content: '', status: 'pending' },
    { title: 'Conclusions', content: '', status: 'pending' },
    { title: 'Limitations', content: '', status: 'pending' },
    { title: 'Future Work', content: '', status: 'pending' },
    { title: 'References', content: '', status: 'pending' },
  ])

  const [isGenerating, setIsGenerating] = useState(false)
  const [generatedReport, setGeneratedReport] = useState<string | null>(null)

  const generateReport = async () => {
    setIsGenerating(true)
    setReportSections(prev => prev.map(s => ({ ...s, status: 'pending' as const })))

    try {
      // Fetch data
      const [statusRes, analyticsRes, verificationRes] = await Promise.all([
        fetch('/api/v1/security/status'),
        fetch('/api/v1/security/analytics'),
        fetch('/api/v1/security/verification/metrics'),
      ])

      const status = (await statusRes.json()).data
      const analytics = (await analyticsRes.json()).data
      const verification = (await verificationRes.json()).data

      // Generate each section
      const sections = [
        generateTitlePage(status),
        generateAbstract(analytics, verification),
        generateIntroduction(),
        generateMethodology(status),
        generateResults(analytics, verification, status),
        generateAnalysis(analytics, verification),
        generateConclusions(analytics),
        generateLimitations(),
        generateFutureWork(),
        generateReferences(),
      ]

      // Simulate section generation with delays
      for (let i = 0; i < sections.length; i++) {
        await new Promise(resolve => setTimeout(resolve, 800))

        setReportSections(prev => {
          const newSections = [...prev]
          newSections[i].status = 'generating'
          return newSections
        })

        await new Promise(resolve => setTimeout(resolve, 1200))

        setReportSections(prev => {
          const newSections = [...prev]
          newSections[i].content = sections[i]
          newSections[i].status = 'complete'
          return newSections
        })
      }

      // Compile full report
      const fullReport = compileFullReport(
        reportSections.map((_, i) => sections[i])
      )

      setGeneratedReport(fullReport)
      setIsGenerating(false)
    } catch (err) {
      console.error('Failed to generate report:', err)
      setIsGenerating(false)
    }
  }

  const downloadReport = () => {
    if (!generatedReport) return

    const blob = new Blob([generatedReport], { type: 'text/plain' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `QShield-Twin-Research-Report-${Date.now()}.txt`
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    URL.revokeObjectURL(url)
  }

  const completedCount = reportSections.filter(s => s.status === 'complete').length
  const progress = Math.round((completedCount / reportSections.length) * 100)

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="border-b border-slate-700 pb-8">
        <h1 className="text-4xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-blue-400 mb-2">
          Research Report Generator
        </h1>
        <p className="text-slate-300">
          Generate a structured report from the current simulation metrics. Output is clearly labelled as
          simulated and not peer-reviewed.
        </p>
      </div>

      {/* Control Panel */}
      <div className="bg-gradient-to-br from-slate-800 to-slate-900 border border-slate-700 rounded-lg p-8">
        <div className="flex flex-col md:flex-row gap-6 items-start md:items-center">
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={generateReport}
            disabled={isGenerating}
            className="flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-700 hover:to-blue-700 disabled:opacity-50 rounded-lg font-semibold transition"
          >
            {isGenerating ? (
              <>
                <Loader size={20} className="animate-spin" />
                Generating...
              </>
            ) : (
              <>
                <FileText size={20} />
                Generate Report
              </>
            )}
          </motion.button>

          {generatedReport && (
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={downloadReport}
              className="flex items-center gap-2 px-6 py-3 bg-emerald-600 hover:bg-emerald-700 rounded-lg font-semibold transition"
            >
              <Download size={20} />
              Download Report
            </motion.button>
          )}

          {isGenerating && (
            <div className="ml-auto flex items-center gap-4">
              <div className="text-right">
                <div className="text-2xl font-bold text-cyan-400">{progress}%</div>
                <div className="text-sm text-slate-400">{completedCount}/{reportSections.length} sections</div>
              </div>
            </div>
          )}
        </div>

        {isGenerating && (
          <div className="mt-6">
            <motion.div
              className="h-2 bg-gradient-to-r from-cyan-500 to-blue-500 rounded-full"
              initial={{ width: 0 }}
              animate={{ width: `${progress}%` }}
              transition={{ duration: 0.5 }}
            />
          </div>
        )}
      </div>

      {/* Report Sections Status */}
      <div className="space-y-3">
        <h2 className="text-lg font-semibold text-slate-100">Report Sections</h2>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
          {reportSections.map((section, idx) => (
            <motion.div
              key={section.title}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.05 }}
              className={`p-4 rounded-lg border transition ${
                section.status === 'complete'
                  ? 'bg-emerald-900/20 border-emerald-500/30'
                  : section.status === 'generating'
                  ? 'bg-cyan-900/20 border-cyan-500/50'
                  : 'bg-slate-800/50 border-slate-700'
              }`}
            >
              <div className="flex items-center justify-between">
                <h3 className="font-medium text-slate-100">{section.title}</h3>
                {section.status === 'complete' && (
                  <Check size={20} className="text-emerald-400" />
                )}
                {section.status === 'generating' && (
                  <motion.div
                    animate={{ rotate: 360 }}
                    transition={{ duration: 2, repeat: Infinity }}
                  >
                    <Loader size={20} className="text-cyan-400" />
                  </motion.div>
                )}
              </div>
              <p className="text-xs text-slate-500 mt-2">
                {section.status === 'complete' ? '✓ Generated' : section.status === 'generating' ? '⟳ In progress' : '○ Pending'}
              </p>
            </motion.div>
          ))}
        </div>
      </div>

      {/* Generated Report Preview */}
      {generatedReport && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-gradient-to-br from-slate-800 to-slate-900 border border-slate-700 rounded-lg p-8"
        >
          <h2 className="text-xl font-bold text-slate-100 mb-4">Report Preview</h2>
          <div className="bg-slate-900 p-6 rounded-lg h-96 overflow-y-auto text-sm text-slate-300 font-mono whitespace-pre-wrap break-words border border-slate-700">
            {generatedReport.substring(0, 2000)}...
          </div>
          <div className="mt-4 text-center text-slate-500 text-sm">
            Report size: {(generatedReport.length / 1024).toFixed(1)} KB
          </div>
        </motion.div>
      )}

      {/* Report Template Information */}
      <div className="bg-gradient-to-br from-slate-800 to-slate-900 border border-slate-700 rounded-lg p-8">
        <h2 className="text-lg font-bold text-slate-100 mb-4">Report Sections</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <ReportInfo
            title="Methodology"
            description="Describes the experimental setup, parameters, and evaluation approach used in the QShield Twin platform."
          />
          <ReportInfo
            title="Results"
            description="Presents detection accuracy metrics, performance benchmarks, and security analysis findings."
          />
          <ReportInfo
            title="Analysis"
            description="Interprets the results, discusses statistical significance, and compares with related work."
          />
          <ReportInfo
            title="Conclusions"
            description="Summarizes key findings and contributions to cybersecurity research."
          />
        </div>
      </div>
    </div>
  )
}

function ReportInfo({ title, description }: { title: string; description: string }) {
  return (
    <div className="p-4 rounded-lg bg-slate-700/30 border border-slate-600">
      <h3 className="font-semibold text-slate-100 mb-2">{title}</h3>
      <p className="text-sm text-slate-400">{description}</p>
    </div>
  )
}

// Report section generators
function generateTitlePage(status: any): string {
  const counters = extractSecurityCounters(status)
  return `
================================================================================
                        QShield Twin Security Research
             Quantum-Resilient Sybil Defense Framework Analysis
================================================================================

Research Report
Generated: ${new Date().toLocaleString()}

Platform: QShield Twin
Framework: Simulated Sybil-Defense Pipeline

Total Devices Analyzed: ${counters.processed_joins}
Legitimate Devices: ${counters.legitimate_devices}
Malicious Nodes Detected: ${counters.ghost_nodes}

${DATA_SOURCE_NOTE}

================================================================================
`
}

function generateAbstract(analytics: any, verification: any): string {
  const detection = extractDetectionMetrics(analytics)
  const vm = extractVerification(verification)

  return `ABSTRACT

This report describes an evaluation run of the QShield Twin cybersecurity
simulation platform and its Sybil-defense pipeline, which combines multi-factor
trust assessment, proof-of-proximity verification, and simulated post-quantum
cryptographic validation.

NOTE ON DATA SOURCE
${DATA_SOURCE_NOTE}

Simulation Results (synthetic ground truth):
- Detection Accuracy: ${(detection.accuracy * 100).toFixed(2)}%
- F1 Score: ${(detection.f1_score * 100).toFixed(2)}%
- False-Positive Rate: ${(detection.false_positive_rate * 100).toFixed(2)}%
- Average Verification Delay: ${vm.avgPropagationMs.toFixed(2)}ms
- Verification Acceptance Rate: ${(vm.acceptanceRate * 100).toFixed(2)}%

Keywords: Sybil Attack Detection, Simulation, IoT Security,
Proximity Verification, Post-Quantum Cryptography (Simulated)

`
}

function generateIntroduction(): string {
  return `INTRODUCTION

Sybil attacks pose a significant threat to distributed IoT networks, where an attacker
can create multiple fake identities (Sybil nodes) to gain disproportionate influence
over network operations. Traditional defense mechanisms are insufficient for modern
quantum-era threats.

This research introduces QShield Twin, a comprehensive cybersecurity platform with
an integrated Quantum-Resilient Sybil Defense Framework. The framework combines:

1. Ghost Node Simulation Engine
   - Realistic Sybil attack generation
   - Configurable attack parameters
   - Statistical attack behavior modeling

2. Proof-of-Proximity Verification (Simulated)
   - Simulated Time-of-Flight distance estimation
   - Confidence scoring with noise modelling
   - Spatial evidence for the trust score (not hardware-verified distance)

3. Post-Quantum Cryptography (Simulated)
   - Synthetic lattice-signature operations (NOT real cryptography)
   - Timing/metrics modelling only
   - Pluggable interface for future liboqs-python integration

4. Multi-Factor Trust Scoring
   - Proximity-based evidence
   - Signature evidence
   - Behavioral anomaly detection
   - Historical reputation tracking

5. Sharded Audit Ledger
   - SHA-256 hash-chained, tamper-evident, sharded storage
   - Append-only local audit trail (single node; not a blockchain)
   - Device blacklist/whitelist management

6. Research-Grade Metrics Collection
   - Precision, Recall, F1 Score, Accuracy
   - Confusion matrix analysis
   - Attack/Defense success rates

`
}

function generateMethodology(status: any): string {
  const counters = extractSecurityCounters(status)
  return `METHODOLOGY

3.1 Experimental Setup

The evaluation platform consists of:
- Simulation Engine: Event-driven discrete simulation using SimPy
- Network Topology: Dynamic network with configurable connectivity
- Security Orchestrator: Central coordinator for security workflow
- WebSocket Dashboard: Real-time visualization and control

3.2 Test Configuration

Legitimate Devices: ${counters.processed_joins}
- Distributed across simulated topology
- Random communication patterns
- Varying trust profiles

Malicious Nodes: ${counters.ghost_nodes}
- Sybil nodes with shared origin
- Coordinated attack behavior
- Packet rate variation

Attack Duration: 30 seconds
Communication Radius: 100 meters
Distance Threshold: 10 meters

3.3 Evaluation Metrics

1. Detection Accuracy
   - True Positive Rate (Recall)
   - False Positive Rate
   - Precision of detection
   - Overall accuracy

2. Performance Metrics
   - Average verification time
   - Ledger growth rate
   - Trust score stability
   - Memory consumption

3. Security Metrics
   - Attack success rate
   - Defense effectiveness
   - Detection latency
   - Recovery time

`
}

function generateResults(analytics: any, verification: any, status: any): string {
  const detection = extractDetectionMetrics(analytics)
  const trust = extractTrust(status)
  const vm = extractVerification(verification)
  const ad = analytics.attack_defense ?? {}
  const cm = analytics.confusion_matrix ?? {}

  return `RESULTS

${DATA_SOURCE_NOTE}

4.1 Detection Accuracy (synthetic ground truth)

Precision:     ${(detection.precision * 100).toFixed(2)}%
Recall:        ${(detection.recall * 100).toFixed(2)}%
F1 Score:      ${(detection.f1_score * 100).toFixed(2)}%
Accuracy:      ${(detection.accuracy * 100).toFixed(2)}%
False-Positive Rate: ${(detection.false_positive_rate * 100).toFixed(2)}%

Confusion matrix:
  True Positives:  ${cm.true_positives ?? 0}
  True Negatives:  ${cm.true_negatives ?? 0}
  False Positives: ${cm.false_positives ?? 0}
  False Negatives: ${cm.false_negatives ?? 0}

The pipeline flagged ${cm.true_positives ?? 0} of the seeded malicious identities
and produced ${cm.false_positives ?? 0} false positives and ${cm.false_negatives ?? 0}
false negatives in this run.

4.2 Verification Performance

Total Verifications:        ${vm.total}
Acceptance Rate:            ${(vm.acceptanceRate * 100).toFixed(2)}%
Average Propagation Delay:  ${vm.avgPropagationMs.toFixed(2)}ms
Average Confidence:         ${(vm.avgConfidence * 100).toFixed(2)}%

4.3 Attack/Defense Statistics

Ghosts Spawned:           ${ad.ghosts_spawned ?? 0}
Ghosts Detected:          ${ad.ghosts_detected ?? 0}
Attack Success Rate:      ${((ad.attack_success_rate ?? 0) * 100).toFixed(2)}%
Defense Success Rate:     ${((ad.defense_success_rate ?? 0) * 100).toFixed(2)}%

4.4 Trust Analysis

Devices Scored:           ${trust.total_devices}
Accepted:                 ${trust.accepted}
Monitored:                ${trust.monitored}
Rejected:                 ${trust.rejected}
Blacklisted:              ${trust.blacklisted}
Average Trust Score:      ${(trust.average * 100).toFixed(2)}/100

`
}

function generateAnalysis(analytics: any, verification: any): string {
  const detection = extractDetectionMetrics(analytics)
  const vm = extractVerification(verification)

  return `ANALYSIS

5.1 Detection Performance

In this simulation run the pipeline reached an F1 score of
${(detection.f1_score * 100).toFixed(2)}% with a false-positive rate of
${(detection.false_positive_rate * 100).toFixed(2)}%. Because the simulator
supplies synthetic ground-truth labels, these figures describe the detector
against the simulator's own scenarios; they are not evidence of real-world
accuracy.

5.2 Verification Effectiveness

Simulated proximity verification accepted ${(vm.acceptanceRate * 100).toFixed(2)}% of
verifications, with an average modelled propagation delay of
${vm.avgPropagationMs.toFixed(2)}ms. These timings are computed from a modelled
speed-of-light path delay and injected sensor noise, not from measured hardware.

5.3 Trust Scoring

Multi-factor trust scoring combined spatial evidence, signature checks, and
behavioural signals. The per-decision distribution is reported in section 4.4.

5.4 Ledger

Records are stored in an 8-way sharded, SHA-256 hash-chained audit ledger. Each
entry commits to its predecessor, so edits or deletions are detectable via the
integrity endpoint. This is a single-node tamper-evident log, not a distributed
consensus system, and scalability has not been benchmarked here.

5.5 Cryptographic Status

The post-quantum cryptographic operations are SIMULATED (synthetic key material
and signatures) and provide no real security. The module presents the same
interface a real liboqs-python backend would, so it can be replaced later.

`
}

function generateConclusions(analytics: any): string {
  const detection = extractDetectionMetrics(analytics)

  return `CONCLUSIONS

Within the simulated scenarios exercised by this run, the QShield Twin pipeline:

1. Classified identities with a detection accuracy of ${(detection.accuracy * 100).toFixed(2)}%
   (F1 ${(detection.f1_score * 100).toFixed(2)}%) against synthetic ground truth.
2. Exercised multi-factor trust scoring (spatial + signature + behavioural signals).
3. Maintained a tamper-evident, hash-chained audit ledger.

These are simulator results. They do not demonstrate production security, real
proximity assurance, or real post-quantum cryptography. See the Limitations
section for the specific caveats.

`
}

function generateLimitations(): string {
  return `LIMITATIONS & THREATS TO VALIDITY

1. Synthetic ground truth. Detection metrics are computed against labels the
   simulator itself assigns. The name-token heuristic and the scenario
   generator share vocabulary, which can inflate apparent detection quality.

2. Simulated cryptography. Post-quantum operations are synthetic and provide no
   security; they only model timing and call structure.

3. Simulated proximity. Distance is derived from a modelled delay and injected
   noise, not from hardware ranging (e.g. UWB). It is not proof of physical
   proximity in the real world.

4. Single-node ledger. The ledger is tamper-evident locally, but there is no
   replication, consensus, or blockchain.

5. No field validation. No real deployment, adversarial testing, or benchmark
   against production traffic has been performed.

`
}

function generateFutureWork(): string {
  return `FUTURE WORK

7.1 Immediate Enhancements

- Integration with liboqs-python for real lattice cryptography
- Real UWB hardware for authentic proximity verification
- Machine learning-based behavioral anomaly detection
- Clustering algorithms for network behavior analysis

7.2 Medium-Term Goals

- Single-node ledger hardening and snapshot/restore tooling
- Multi-hop packet verification
- Real-time threat intelligence sharing
- Multi-node (federated) orchestration design

7.3 Long-Term Vision

- Autonomous threat response and mitigation
- Cross-network federation protocols
- AI-powered predictive attack detection
- Integration with commercial IoT platforms

7.4 Research Directions

- Quantum-safe key distribution networks
- Proof-of-Proximity in mobile scenarios
- Sybil attack resilience in sparse networks
- Lightweight cryptography for resource-constrained devices

`
}

function generateReferences(): string {
  return `REFERENCES

[1] Douceur, J. R. (2002). "The Sybil Attack." Proceedings of the 1st International
    Workshop on Peer-to-Peer Systems (IPTPS).

[2] Cerpa, A., et al. (2003). "Habitat Monitoring with Sensor Networks."
    ACM SIGCOMM Computer Communication Review, 34(1).

[3] National Institute of Standards and Technology (2022).
    "Post-Quantum Cryptography: FIPS 203, 204, 205."

[4] Newsome, J., et al. (2004). "The Sybil Attack in Sensor Networks: Analysis and
    Defenses." Proceedings of the 3rd ACM/IEEE IPSN.

[5] Han, R., et al. (2002). "A Taxonomy of Timing Channels."
    Proceedings of the ACM Workshop on Privacy in the Electronic Society.

[6] Laurie, B., & Clayton, R. (2004). "'Proof' of Work' Proves Not to Work."
    Financial Cryptography and Data Security.

[7] Levine, B. N., et al. (2006). "Advogato's Trust Metric."
    Proceedings of the 15th International WWW Conference.

[8] Maymounkov, P., & Mazières, D. (2002). "Kademlia: A Peer-to-Peer Information
    System Based on the XOR Metric."

---
End of Report
`
}

function compileFullReport(sections: string[]): string {
  return sections.join('\n')
}
